  ('IO-SRC-MN-0003', 'IO-CM-MN-0001', 'The Sangai Express', 'MGSF threatens to intensify cease-work strike in Manipur', null, 'https://www.thesangaiexpress.com/Encyc/2026/7/10/waari-singbul-network-imphal-jul-9-the-manipur-government-services-federation-mgsf-has-threatened-to-intensify.html', '2026-07-10', 'Original media reporting', 'original_independent', 'Local reporting naming the federation and its continuing demands.', '2026-07-15', 'No correction identified', null, 'Lead'),
  ('IO-SRC-MN-0004', 'IO-CM-MN-0001', 'The Sangai Express', 'MGSF strike continues after Saturday holiday restored', null, 'https://www.thesangaiexpress.com/Encyc/2026/7/11/by-our-staff-reporter-imphal-jul-10-even-as-the-saturday-holiday-for-government-employees-has-been-restored-th.html', '2026-07-11', 'Follow-up media reporting', 'same_publisher_follow_up', 'Same-publisher follow-up confirming continuation after the partial response.', '2026-07-15', 'No correction identified', null, 'Follow-up'),
  ('IO-SRC-MN-0005', 'IO-CM-MN-0001', 'The Sangai Express', 'Manipur employees set to begin cease-work strike from 1 July', null, 'https://www.thesangaiexpress.com/Encyc/2026/7/1/imphal-jun-30-employees-of-the-state-government-are-all-set-to-launch-a-ceasework-strike-from-wednesday-until-.html', '2026-07-01', 'Original media reporting', 'same_publisher_follow_up', 'Provides launch chronology and the organising body''s demand charter. It does not by itself verify later participation levels.', '2026-07-15', 'No correction identified', null, 'Historical context'),
  ('IO-SRC-OD-0001', 'IO-CM-OD-0001', 'The New Indian Express', 'Dharmasala high-school students stage protest over teacher shortage', null, 'https://www.newindianexpress.com/states/odisha/2026/Jul/11/dharmasala-high-school-students-stage-protest-over-teacher-shortage', '2026-07-11', 'Original media reporting', 'original_independent', 'Independent local report documenting the protest and response. Teacher and student figures differ from The Times of India and remain visible as a discrepancy.', '2026-07-15', 'No correction identified', null, 'Corroboration'),
  ('IO-SRC-OD-0002', 'IO-CM-OD-0001', 'The Times of India', 'School students lock gate, stage dharna over teacher shortage', null, 'https://timesofindia.indiatimes.com/city/bhubaneswar/school-students-lock-gate-stage-dharna-over-teacher-shortage/articleshow/132310990.cms', '2026-07-11', 'Original media reporting', 'original_independent', 'Independent corroboration of the event and outcome. It reports different current-teacher and student totals, which require official school records.', '2026-07-15', 'No correction identified', null, 'Corroboration'),
  ('IO-SRC-UK-0001', 'IO-CM-UK-0001', 'Mohammad Aman (@MohammadAman48)', 'Roadside environmental appeal about tree felling in Uttarakhand', null, 'https://x.com/MohammadAman48/status/2077721151774810616', '2026-07-16', 'Social media lead', 'unknown', 'User-provided X lead. The supplied screenshot shows an on-camera environmental appeal beside felled trees and references Rishikesh/Uttarakhand. Exact capture date, precise location, original uploader and relationship to the documented protest are not yet established. Do not treat the post''s oxygen claims as verified factual evidence.', '2026-07-17', 'No correction identified', 'User-supplied screenshot retained in the conversation; original media not archived', 'Lead'),
  ('IO-SRC-UK-0002', 'IO-CM-UK-0001', 'Swati Negi (@swatinegi2)', 'Additional X visual lead concerning the Bhaniyawala–Rishikesh tree-felling issue', null, 'https://x.com/swatinegi2/status/2077765341711888588', '2026-07-16', 'Social media lead', 'unknown', 'User-provided lead. The full post and media were not captured in the reviewed source set. Event match, source family, original uploader, date, location, integrity and privacy/safety status remain pending. Do not count this post as independent corroboration.', '2026-07-17', 'No correction identified', null, 'Lead'),
  ('IO-SRC-UK-0003', 'IO-CM-UK-0001', 'Avikal Uttarakhand', 'ऋषिकेश-भानियावाला हाईवे पर पेड़ कटान का विरोध', 'Avikal Uttarakhand', 'https://avikaluttarakhand.com/uttarakhand/protest-against-tree-felling-on-the-rishikesh-bhaniyawala-highway/', '2026-07-08', 'Original media reporting', 'original_independent', 'Independent local report documenting a protest at the NHAI office and the stated environmental demands. Participant assertions about project justification, wildlife impacts and tree totals remain attributed.', '2026-07-17', 'No correction identified', null, 'Corroboration'),
  ('IO-SRC-UK-0004', 'IO-CM-UK-0001', 'The Times of India', 'Residents hug trees to stop felling along Bhaniyawala-R’kesh stretch', 'Shivani Azad', 'https://timesofindia.indiatimes.com/city/dehradun/residents-hug-trees-to-stop-felling-along-bhaniyawala-rkesh-stretch/articleshow/132336173.cms', '2026-07-11', 'Original media reporting', 'original_independent', 'Original local reporting with photographs, protest-duration information, participant accounts and an attributed NHAI response. Claims about environmental effects and the precise tree total remain attributed or disputed.', '2026-07-17', 'No correction identified', null, 'Corroboration'),
  ('IO-SRC-UK-0005', 'IO-CM-UK-0001', 'The Times of India', '2 held, FIR against 2 dozen as tree felling resumes on Rishikesh-Bhaniyawala stretch', 'Shivani Azad', 'https://timesofindia.indiatimes.com/city/dehradun/2-held-fir-against-2-dozen-as-tree-felling-resumes-on-rishikesh-bhaniyawala-stretch/articleshow/132375064.cms', '2026-07-14', 'Follow-up media reporting', 'same_publisher_follow_up', 'Same-publisher follow-up documenting resumption of felling, police deployment, arrests and an FIR. The police allegations are attributed and are not treated as judicial findings.', '2026-07-17', 'No correction identified', null, 'Follow-up'),
  ('IO-SRC-UK-0006', 'IO-CM-UK-0001', 'Press Information Bureau / Ministry of Road Transport and Highways', 'Bhaniyawala–Jollygrant–Rishikesh Four/Six Laning Project: A Highway Designed for the Future, Built with Wildlife Conservation at its Core', null, 'https://www.pib.gov.in/PressReleasePage.aspx?PRID=2282251&lang=2&reg=48', '2026-07-07', 'Official government source', 'official_primary_source', 'Official project context on route length, estimated cost, reduced right of way, transplantation and wildlife-mitigation measures. It does not independently verify protest occurrence or resolve disputed environmental impacts.', '2026-07-17', 'No correction identified', null, 'Official context'),
  ('IO-SRC-HR-0001', 'IO-CM-HR-0001', 'The Indian Express', 'Farmers hold protests across Haryana, oppose new Rabi procurement rules', null, 'https://indianexpress.com/article/cities/chandigarh/farmers-hold-protests-across-haryana-oppose-new-rabi-procurement-rules-10631410/', '2026-04-11', 'Original media reporting', 'original_independent', 'Supports the event occurrence and listed source role. The scale of exclusion, technical failures and eventual settlement remain incompletely documented.', '2026-07-17', 'No correction identified', null, 'Lead'),
